CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- Table: blog_categories
CREATE TABLE IF NOT EXISTS blog_categories (
	id VARCHAR(50) NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	slug VARCHAR(100) NOT NULL, 
	display_order INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name)
);

-- Table: bulk_enquiries
CREATE TABLE IF NOT EXISTS bulk_enquiries (
	id UUID NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	company_name VARCHAR(150), 
	email VARCHAR(255) NOT NULL, 
	phone VARCHAR(20) NOT NULL, 
	category VARCHAR(100) NOT NULL, 
	quantity VARCHAR(100) NOT NULL, 
	destination VARCHAR(150), 
	notes TEXT, 
	status VARCHAR(30) NOT NULL, 
	vendor_notes TEXT, 
	created_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id)
);

-- Table: categories
CREATE TABLE IF NOT EXISTS categories (
	id VARCHAR(50) NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	slug VARCHAR(100) NOT NULL, 
	tagline VARCHAR(255), 
	image_url TEXT NOT NULL, 
	display_order INTEGER NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name)
);

-- Table: contact_messages
CREATE TABLE IF NOT EXISTS contact_messages (
	id UUID NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	email VARCHAR(255) NOT NULL, 
	phone VARCHAR(20) NOT NULL, 
	subject VARCHAR(200) NOT NULL, 
	message TEXT NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	vendor_notes TEXT, 
	created_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id)
);

-- Table: coupons
CREATE TABLE IF NOT EXISTS coupons (
	id UUID NOT NULL, 
	code VARCHAR(50) NOT NULL, 
	description VARCHAR(255) NOT NULL, 
	discount_type VARCHAR(20) NOT NULL, 
	discount_value NUMERIC(10, 2) NOT NULL, 
	min_order_amount NUMERIC(10, 2) NOT NULL, 
	max_discount NUMERIC(10, 2), 
	valid_from TIMESTAMP WITH TIME ZONE NOT NULL, 
	valid_until TIMESTAMP WITH TIME ZONE, 
	usage_limit_per_user INTEGER NOT NULL, 
	is_first_order_only BOOLEAN NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id)
);

-- Table: email_logs
CREATE TABLE IF NOT EXISTS email_logs (
	id UUID NOT NULL, 
	recipient_email VARCHAR(255) NOT NULL, 
	template_key VARCHAR(100) NOT NULL, 
	subject VARCHAR(255) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	error_message TEXT, 
	sent_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id)
);

-- Table: email_templates
CREATE TABLE IF NOT EXISTS email_templates (
	id UUID NOT NULL, 
	template_key VARCHAR(100) NOT NULL, 
	name VARCHAR(150) NOT NULL, 
	subject VARCHAR(255) NOT NULL, 
	body_html TEXT NOT NULL, 
	body_text TEXT NOT NULL, 
	available_variables JSONB NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE, 
	updated_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id)
);

-- Table: newsletter_subscribers
CREATE TABLE IF NOT EXISTS newsletter_subscribers (
	id UUID NOT NULL, 
	email VARCHAR(255) NOT NULL, 
	coupon_code VARCHAR(50) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	subscribed_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id)
);

-- Table: otp_verifications
CREATE TABLE IF NOT EXISTS otp_verifications (
	id UUID NOT NULL, 
	identifier VARCHAR(255) NOT NULL, 
	otp_hash VARCHAR(255) NOT NULL, 
	channel VARCHAR(20) NOT NULL, 
	attempts INTEGER NOT NULL, 
	expires_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	is_used BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id)
);

-- Table: promo_banners
CREATE TABLE IF NOT EXISTS promo_banners (
	id UUID NOT NULL, 
	title VARCHAR(150) NOT NULL, 
	subtitle VARCHAR(255), 
	badge VARCHAR(50), 
	cta_label VARCHAR(50) NOT NULL, 
	cta_link VARCHAR(255) NOT NULL, 
	image_url TEXT NOT NULL, 
	display_order INTEGER NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	PRIMARY KEY (id)
);

-- Table: site_settings
CREATE TABLE IF NOT EXISTS site_settings (
	key VARCHAR(100) NOT NULL, 
	value JSONB NOT NULL, 
	description VARCHAR(255), 
	updated_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (key)
);

-- Table: testimonials
CREATE TABLE IF NOT EXISTS testimonials (
	id UUID NOT NULL, 
	customer_name VARCHAR(100) NOT NULL, 
	location VARCHAR(100) NOT NULL, 
	rating INTEGER NOT NULL, 
	review_text TEXT NOT NULL, 
	product_name VARCHAR(150), 
	is_featured BOOLEAN NOT NULL, 
	display_order INTEGER NOT NULL, 
	PRIMARY KEY (id)
);

-- Table: users
CREATE TABLE IF NOT EXISTS users (
	id UUID NOT NULL, 
	phone VARCHAR(15), 
	email VARCHAR(255), 
	password_hash VARCHAR(255), 
	full_name VARCHAR(100) NOT NULL, 
	avatar_url TEXT, 
	role VARCHAR(20) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	is_verified BOOLEAN NOT NULL, 
	dietary_preference VARCHAR(50), 
	newsletter_subscribed BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE, 
	updated_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id)
);

-- Table: why_choose_features
CREATE TABLE IF NOT EXISTS why_choose_features (
	id UUID NOT NULL, 
	icon_name VARCHAR(50) NOT NULL, 
	title VARCHAR(100) NOT NULL, 
	description VARCHAR(255) NOT NULL, 
	display_order INTEGER NOT NULL, 
	PRIMARY KEY (id)
);

-- Table: audit_logs
CREATE TABLE IF NOT EXISTS audit_logs (
	id UUID NOT NULL, 
	user_id UUID, 
	action VARCHAR(100) NOT NULL, 
	entity_type VARCHAR(50) NOT NULL, 
	entity_id VARCHAR(150) NOT NULL, 
	changes JSONB, 
	ip_address VARCHAR(45), 
	created_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE SET NULL
);

-- Table: loyalty_ledger
CREATE TABLE IF NOT EXISTS loyalty_ledger (
	id UUID NOT NULL, 
	user_id UUID NOT NULL, 
	points INTEGER NOT NULL, 
	activity_type VARCHAR(50) NOT NULL, 
	reference_id VARCHAR(100), 
	balance_after INTEGER NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

-- Table: products
CREATE TABLE IF NOT EXISTS products (
	id VARCHAR(150) NOT NULL, 
	category_id VARCHAR(50) NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	subtitle VARCHAR(255), 
	description TEXT NOT NULL, 
	origin VARCHAR(150), 
	tag VARCHAR(50), 
	rating NUMERIC(2, 1) NOT NULL, 
	reviews_count INTEGER NOT NULL, 
	in_stock BOOLEAN NOT NULL, 
	health_benefits TEXT, 
	ingredients TEXT, 
	storage_instructions TEXT, 
	common_uses TEXT, 
	additional_info TEXT, 
	is_featured BOOLEAN NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE, 
	updated_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(category_id) REFERENCES categories (id) ON DELETE RESTRICT
);

-- Table: user_addresses
CREATE TABLE IF NOT EXISTS user_addresses (
	id UUID NOT NULL, 
	user_id UUID NOT NULL, 
	label VARCHAR(30), 
	recipient_name VARCHAR(100) NOT NULL, 
	recipient_phone VARCHAR(15) NOT NULL, 
	flat_no VARCHAR(100) NOT NULL, 
	street VARCHAR(255) NOT NULL, 
	landmark VARCHAR(150), 
	city VARCHAR(100) NOT NULL, 
	state VARCHAR(100) NOT NULL, 
	pincode VARCHAR(10) NOT NULL, 
	is_default_shipping BOOLEAN NOT NULL, 
	is_default_billing BOOLEAN NOT NULL, 
	delivery_instructions TEXT, 
	created_at TIMESTAMP WITH TIME ZONE, 
	updated_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

-- Table: user_sessions
CREATE TABLE IF NOT EXISTS user_sessions (
	id UUID NOT NULL, 
	user_id UUID NOT NULL, 
	refresh_token_hash VARCHAR(255) NOT NULL, 
	device_info VARCHAR(255), 
	ip_address VARCHAR(45), 
	last_active TIMESTAMP WITH TIME ZONE, 
	expires_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	is_revoked BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

-- Table: wishlist_items
CREATE TABLE IF NOT EXISTS wishlist_items (
	id UUID NOT NULL, 
	user_id UUID, 
	guest_session_token VARCHAR(100), 
	product_id VARCHAR(150) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

-- Table: blog_posts
CREATE TABLE IF NOT EXISTS blog_posts (
	id VARCHAR(100) NOT NULL, 
	title VARCHAR(255) NOT NULL, 
	slug VARCHAR(255) NOT NULL, 
	summary TEXT NOT NULL, 
	read_time VARCHAR(30) NOT NULL, 
	image_url TEXT NOT NULL, 
	category_id VARCHAR(50), 
	author_name VARCHAR(100) NOT NULL, 
	author_role VARCHAR(100) NOT NULL, 
	health_tip TEXT, 
	tags TEXT[] NOT NULL, 
	content JSONB NOT NULL, 
	key_benefits TEXT[] NOT NULL, 
	featured_product_id VARCHAR(150), 
	is_published BOOLEAN NOT NULL, 
	published_at TIMESTAMP WITH TIME ZONE, 
	created_at TIMESTAMP WITH TIME ZONE, 
	updated_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(category_id) REFERENCES blog_categories (id) ON DELETE SET NULL, 
	FOREIGN KEY(featured_product_id) REFERENCES products (id) ON DELETE SET NULL
);

-- Table: harvest_batches
CREATE TABLE IF NOT EXISTS harvest_batches (
	id UUID NOT NULL, 
	product_id VARCHAR(150) NOT NULL, 
	batch_code VARCHAR(50) NOT NULL, 
	farmer_cluster VARCHAR(150) NOT NULL, 
	harvest_date DATE NOT NULL, 
	lab_report_url TEXT, 
	fssai_license VARCHAR(50), 
	PRIMARY KEY (id), 
	FOREIGN KEY(product_id) REFERENCES products (id) ON DELETE CASCADE
);

-- Table: orders
CREATE TABLE IF NOT EXISTS orders (
	id UUID NOT NULL, 
	order_number VARCHAR(50) NOT NULL, 
	user_id UUID, 
	customer_name VARCHAR(100) NOT NULL, 
	customer_phone VARCHAR(15) NOT NULL, 
	customer_email VARCHAR(255) NOT NULL, 
	shipping_address_id UUID, 
	shipping_flat_no VARCHAR(100) NOT NULL, 
	shipping_street VARCHAR(255) NOT NULL, 
	shipping_landmark VARCHAR(150), 
	shipping_city VARCHAR(100) NOT NULL, 
	shipping_state VARCHAR(100) NOT NULL, 
	shipping_pincode VARCHAR(10) NOT NULL, 
	order_notes TEXT, 
	subtotal NUMERIC(10, 2) NOT NULL, 
	shipping_fee NUMERIC(10, 2) NOT NULL, 
	discount_amount NUMERIC(10, 2) NOT NULL, 
	loyalty_coins_redeemed INTEGER NOT NULL, 
	total_amount NUMERIC(10, 2) NOT NULL, 
	payment_method VARCHAR(50) NOT NULL, 
	order_status VARCHAR(30) NOT NULL, 
	courier_name VARCHAR(100), 
	tracking_awb VARCHAR(100), 
	invoice_pdf_url TEXT, 
	vendor_notes TEXT, 
	created_at TIMESTAMP WITH TIME ZONE, 
	updated_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE SET NULL, 
	FOREIGN KEY(shipping_address_id) REFERENCES user_addresses (id) ON DELETE SET NULL
);

-- Table: product_faqs
CREATE TABLE IF NOT EXISTS product_faqs (
	id UUID NOT NULL, 
	product_id VARCHAR(150) NOT NULL, 
	question TEXT NOT NULL, 
	asked_by_name VARCHAR(100) NOT NULL, 
	answer TEXT, 
	answered_by VARCHAR(100), 
	is_published BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(product_id) REFERENCES products (id) ON DELETE CASCADE
);

-- Table: product_features
CREATE TABLE IF NOT EXISTS product_features (
	id UUID NOT NULL, 
	product_id VARCHAR(150) NOT NULL, 
	feature_text VARCHAR(255) NOT NULL, 
	display_order INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(product_id) REFERENCES products (id) ON DELETE CASCADE
);

-- Table: product_images
CREATE TABLE IF NOT EXISTS product_images (
	id UUID NOT NULL, 
	product_id VARCHAR(150) NOT NULL, 
	image_url TEXT NOT NULL, 
	is_primary BOOLEAN NOT NULL, 
	display_order INTEGER NOT NULL, 
	alt_text VARCHAR(255), 
	PRIMARY KEY (id), 
	FOREIGN KEY(product_id) REFERENCES products (id) ON DELETE CASCADE
);

-- Table: product_nutritional_facts
CREATE TABLE IF NOT EXISTS product_nutritional_facts (
	id UUID NOT NULL, 
	product_id VARCHAR(150) NOT NULL, 
	nutrient_name VARCHAR(100) NOT NULL, 
	nutrient_value VARCHAR(100) NOT NULL, 
	display_order INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(product_id) REFERENCES products (id) ON DELETE CASCADE
);

-- Table: product_purity_parameters
CREATE TABLE IF NOT EXISTS product_purity_parameters (
	id UUID NOT NULL, 
	product_id VARCHAR(150) NOT NULL, 
	param_name VARCHAR(100) NOT NULL, 
	param_value VARCHAR(100) NOT NULL, 
	display_order INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(product_id) REFERENCES products (id) ON DELETE CASCADE
);

-- Table: product_reviews
CREATE TABLE IF NOT EXISTS product_reviews (
	id UUID NOT NULL, 
	product_id VARCHAR(150) NOT NULL, 
	user_id UUID, 
	author_name VARCHAR(100) NOT NULL, 
	rating INTEGER NOT NULL, 
	title VARCHAR(150), 
	comment TEXT NOT NULL, 
	images TEXT[] NOT NULL, 
	is_verified_buyer BOOLEAN NOT NULL, 
	is_approved BOOLEAN NOT NULL, 
	helpful_votes INTEGER NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(product_id) REFERENCES products (id) ON DELETE CASCADE, 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE SET NULL
);

-- Table: product_variants
CREATE TABLE IF NOT EXISTS product_variants (
	id UUID NOT NULL, 
	product_id VARCHAR(150) NOT NULL, 
	weight_label VARCHAR(50) NOT NULL, 
	price NUMERIC(10, 2) NOT NULL, 
	original_price NUMERIC(10, 2) NOT NULL, 
	discount_label VARCHAR(20), 
	stock_quantity INTEGER NOT NULL, 
	sku VARCHAR(50), 
	is_default BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(product_id) REFERENCES products (id) ON DELETE CASCADE, 
	UNIQUE (sku)
);

-- Table: blog_nutritional_highlights
CREATE TABLE IF NOT EXISTS blog_nutritional_highlights (
	id UUID NOT NULL, 
	post_id VARCHAR(100) NOT NULL, 
	label VARCHAR(100) NOT NULL, 
	value VARCHAR(100) NOT NULL, 
	display_order INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(post_id) REFERENCES blog_posts (id) ON DELETE CASCADE
);

-- Table: cart_items
CREATE TABLE IF NOT EXISTS cart_items (
	id UUID NOT NULL, 
	user_id UUID, 
	guest_session_token VARCHAR(100), 
	product_id VARCHAR(150) NOT NULL, 
	variant_id UUID, 
	weight_label VARCHAR(50), 
	quantity INTEGER NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE, 
	updated_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
	FOREIGN KEY(product_id) REFERENCES products (id) ON DELETE CASCADE, 
	FOREIGN KEY(variant_id) REFERENCES product_variants (id) ON DELETE CASCADE
);

-- Table: coupon_redemptions
CREATE TABLE IF NOT EXISTS coupon_redemptions (
	id UUID NOT NULL, 
	coupon_id UUID NOT NULL, 
	user_id UUID, 
	device_token VARCHAR(100) NOT NULL, 
	customer_phone VARCHAR(25) NOT NULL, 
	customer_email VARCHAR(255), 
	order_id UUID, 
	redeemed_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(coupon_id) REFERENCES coupons (id) ON DELETE CASCADE, 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE SET NULL, 
	FOREIGN KEY(order_id) REFERENCES orders (id) ON DELETE SET NULL
);

-- Table: order_items
CREATE TABLE IF NOT EXISTS order_items (
	id UUID NOT NULL, 
	order_id UUID NOT NULL, 
	product_id VARCHAR(150), 
	variant_id UUID, 
	product_name VARCHAR(255) NOT NULL, 
	weight_label VARCHAR(50) NOT NULL, 
	unit_price NUMERIC(10, 2) NOT NULL, 
	quantity INTEGER NOT NULL, 
	line_total NUMERIC(10, 2) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(order_id) REFERENCES orders (id) ON DELETE CASCADE, 
	FOREIGN KEY(product_id) REFERENCES products (id) ON DELETE SET NULL, 
	FOREIGN KEY(variant_id) REFERENCES product_variants (id) ON DELETE SET NULL
);

-- Table: order_returns
CREATE TABLE IF NOT EXISTS order_returns (
	id UUID NOT NULL, 
	order_id UUID NOT NULL, 
	reason VARCHAR(255) NOT NULL, 
	description TEXT NOT NULL, 
	evidence_images TEXT[] NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	vendor_action_notes TEXT, 
	created_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(order_id) REFERENCES orders (id) ON DELETE CASCADE
);

-- Table: order_tracking_events
CREATE TABLE IF NOT EXISTS order_tracking_events (
	id UUID NOT NULL, 
	order_id UUID NOT NULL, 
	status VARCHAR(50) NOT NULL, 
	title VARCHAR(100) NOT NULL, 
	description VARCHAR(255) NOT NULL, 
	location VARCHAR(100), 
	timestamp TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(order_id) REFERENCES orders (id) ON DELETE CASCADE
);

