INSERT INTO "testimonials" ("id", "customer_name", "location", "rating", "review_text", "product_name", "is_featured", "display_order") VALUES ('8614b69ffc944ed89c843814fcdc88d9'::uuid, 'Priya Sharma', 'New Delhi', 5, 'The Toor Dal quality is exceptional — no polish, no wax, just pure desi dal like my grandmother used to buy. My family can taste the difference!', 'Organic Toor Dal', TRUE, 1) ON CONFLICT DO NOTHING;
INSERT INTO "testimonials" ("id", "customer_name", "location", "rating", "review_text", "product_name", "is_featured", "display_order") VALUES ('3dc445786ec74206b4ffc62b57744f85'::uuid, 'Rajesh Patel', 'Ahmedabad', 5, 'Finally found authentic cold-pressed mustard oil and A2 Bilona Ghee. The aroma itself tells you this is the real thing. Superb quality!', 'A2 Bilona Ghee', TRUE, 2) ON CONFLICT DO NOTHING;
INSERT INTO "testimonials" ("id", "customer_name", "location", "rating", "review_text", "product_name", "is_featured", "display_order") VALUES ('4c8ebdbc904649cdb7ba956b1b9c9aa2'::uuid, 'Sneha Iyer', 'Bangalore', 5, 'I ordered millets and honey — both arrived fresh and well-packed. The wild forest honey crystallizes naturally, which proves it is pure.', 'Wild Forest Honey', TRUE, 3) ON CONFLICT DO NOTHING;
INSERT INTO "testimonials" ("id", "customer_name", "location", "rating", "review_text", "product_name", "is_featured", "display_order") VALUES ('7cb4e97a9b2c41518fa299984d975e52'::uuid, 'Arun Verma', 'Lucknow', 5, 'Running a small restaurant, I switched to ONAAR spices and the feedback from customers has been incredible. Authentic taste in every dish.', 'Garam Masala Powder', TRUE, 4) ON CONFLICT DO NOTHING;
INSERT INTO "testimonials" ("id", "customer_name", "location", "rating", "review_text", "product_name", "is_featured", "display_order") VALUES ('bd09e71778c94c1ab6be66dd142f5cd0'::uuid, 'Meera Krishnan', 'Chennai', 5, 'The Kashmiri almonds and walnuts are premium quality. My children love snacking on these instead of processed junk food. Thank you!', 'Kashmiri Almonds', TRUE, 5) ON CONFLICT DO NOTHING;
INSERT INTO "testimonials" ("id", "customer_name", "location", "rating", "review_text", "product_name", "is_featured", "display_order") VALUES ('9b24a98dd15140519ea620fbe93e401c'::uuid, 'Vikram Singh', 'Jaipur', 5, 'Bulk ordered rice and wheat for the whole family. Sharbati atta chapatis are softer and more nutritious than any branded flour in market.', 'Sharbati Wheat Atta', TRUE, 6) ON CONFLICT DO NOTHING;
