INSERT INTO "products" ("id", "category_id", "name", "subtitle", "description", "origin", "tag", "rating", "reviews_count", "in_stock", "health_benefits", "ingredients", "storage_instructions", "common_uses", "additional_info", "is_featured", "is_active", "created_at", "updated_at") VALUES ('pulses-organic-arhar-dal-toor-dal-pige', 'pulses', 'Organic Arhar Dal / Toor Dal / Pigeon Pea Split', '100% Certified Organic • Unpolished & Natural', 'Organic Arhar Dal / Toor Dal / Pigeon Pea Split is a pantry staple suitable for everyday Indian cooking. Split pigeon pea can be used in traditional dals, curries, soups and other regional recipes. Clean, dry and cook thoroughly before consumption. Product grade, cleaning/polishing status and organic certification should be verified against the supplied batch.', 'Sehore, Madhya Pradesh', 'Certified Organic', 4.7, 22, TRUE, 'Pulses generally provide plant-based protein, dietary fibre and carbohydrates. Nutrient content varies by variety and processing; avoid specific medical or disease-prevention claims unless supported by verified product testing.', 'Split pigeon pea (single ingredient; verify against final pack label).', 'Store in a cool, dry place away from direct sunlight and moisture. After opening, keep in an airtight food-grade container. Use a clean, dry scoop.', 'Suitable for dal, curry, soups, stews, khichdi and other recipes depending on the pulse variety. Soaking and cooking time vary by product.', 'Category: Pulses | Reference bulk rate: ₹180/kg (October 2024 list; NOT a current quote) | GST shown in reference list: 0% | NPOP column in reference list: Y | Minimum bulk pack shown in reference list: 30/50 kg. Confirm current rate, GST, certification, packaging, availability and exact blend/grade with supplier before publishing.', FALSE, TRUE, '2026-11-09 18:43:38.544356'::timestamptz, '2026-11-09 18:43:38.544360'::timestamptz) ON CONFLICT DO NOTHING;
